108	        this.petMapper = petMapper;
109	        this.visitMapper = visitMapper;
110	        this.telephoneNormalizer = telephoneNormalizer;
111	        this.addressNormalizer = addressNormalizer;
112	        this.emailNormalizer = emailNormalizer;
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        owners.forEach(this::populateHouseholdMemberCount);
128	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
134	        Owner owner = this.clinicService.findOwnerById(ownerId);
135	        if (owner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        populateHouseholdMemberCount(owner);
139	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        normalizeAndValidate(ownerFieldsDto);
146	        HttpHeaders headers = new HttpHeaders();
147	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
148	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
149	        owner.setNamesakeCount(countNamesakes(owner));
150	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
151	        assignHousehold(owner, ownerFieldsDto);
152	        this.clinicService.saveOwner(owner);
153	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
154	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
155	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount()));
156	        populateHouseholdMemberCount(owner);
157	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
158	        headers.setLocation(UriComponentsBuilder.newInstance()
159	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
160	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
161	    }
162	
163	    /**
164	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
165	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
166	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
167	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
168	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
169	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
170	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
171	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
172	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly.
173	     *
174	     * @param ownerFieldsDto the incoming owner payload, mutated in place
175	     * @throws MissingOwnerFieldsException if any required field is missing or blank
176	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
177	     */
178	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
179	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
180	        validateRequiredFields(ownerFieldsDto);
181	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
182	        ownerFieldsDto.setTelephone(telephone);
183	        requireUniqueTelephone(telephone);
184	        requireUniqueHousehold(ownerFieldsDto);
185	        requireCityHasCapacity(ownerFieldsDto.getCity());
186	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
187	        ownerFieldsDto.setRegistrationDate(registrationDate);
188	        requireDailyLimitNotReached(registrationDate);
189	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
190	    }
191	
192	    /**
193	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
194	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
195	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day.
196	     *
197	     * @param ownerFieldsDto the incoming owner payload
198	     * @return the effective registration date rolled forward onto a business day
199	     */
200	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
201	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
202	        if (effective == null) {
203	            effective = LocalDate.now();
204	        }
205	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
206	            effective = effective.plusDays(1);
207	        }
208	        return effective;
209	    }
210	
211	    /**
212	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
213	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
214	     * further owner may be created for that day.
215	     *
216	     * @param registrationDate the adjusted business-day registration date of the owner being created
217	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
218	     */
219	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
220	        long createdThatDay = this.clinicService.findAllOwners().stream()
221	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
222	            .count();
223	        if (createdThatDay >= MAX_OWNERS_PER_DAY) {
224	            throw new DailyOwnerLimitExceededException(
225	                "the maximum number of owners for today has already been reached");
226	        }
227	    }
228	
229	    /**
230	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
231	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
232	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
233	     * reflects only owners that predate it.
234	     *
235	     * @param registrationDate the adjusted business-day registration date of the owner being created
236	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
237	     */
238	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
239	        long createdThatDay = this.clinicService.findAllOwners().stream()
240	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
241	            .count();
242	        return createdThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
243	    }
244	
245	    /**
246	     * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}. {@code CITY3} is the upper-cased
247	     * first three letters of the city, {@code LAST3} the upper-cased first three letters of the last name, and
248	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of owners already in that
249	     * city (e.g. {@code LON-SMI-0007}).
250	     *
251	     * @param city     the owner's city
252	     * @param lastName the owner's last name
253	     * @return the generated customer code
254	     */
255	    private String generateCustomerCode(String city, String lastName) {
256	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase();
257	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
258	        int sequence = (int) this.clinicService.findAllOwners().stream()
259	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
260	            .count() + 1;
261	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
262	    }
263	
264	    /**
265	     * Counts how many existing owners already share the given owner's first and last name, compared
266	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
267	     * create; it is zero when the owner's name is unique.
268	     *
269	     * @param owner the newly mapped owner about to be saved
270	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
271	     */
272	    private int countNamesakes(Owner owner) {
273	        String firstName = owner.getFirstName();
274	        String lastName = owner.getLastName();
275	        return (int) this.clinicService.findAllOwners().stream()
276	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
277	                && lastName.equalsIgnoreCase(existing.getLastName()))
278	            .count();
279	    }
280	
281	    /**
282	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
283	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
284	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
285	     *
286	     * @param ownerFieldsDto the owner payload to validate
287	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
288	     */
289	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
290	        List<String> missingFields = new ArrayList<>();
291	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
292	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
293	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
294	        requireText(missingFields, "city", ownerFieldsDto.getCity());
295	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
296	        if (!missingFields.isEmpty()) {
297	            throw new MissingOwnerFieldsException(missingFields);
298	        }
299	    }
300	
301	    private void requireText(List<String> missingFields, String fieldName, String value) {
302	        if (value == null || value.isBlank()) {
303	            missingFields.add(fieldName);
304	        }
305	    }
306	
307	    /**
308	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
309	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
310	     * originally formatted.
311	     *
312	     * @param telephone the normalized telephone of the owner being created
313	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
314	     */
315	    private void requireUniqueTelephone(String telephone) {
316	        boolean inUse = this.clinicService.findAllOwners().stream()
317	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
318	            .anyMatch(telephone::equals);
319	        if (inUse) {
320	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
321	        }
322	    }
323	
324	    /**
325	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
326	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
327	     *
328	     * @param city the city of the owner being created
329	     * @throws OwnerCityFullException if the city already contains 50 or more owners
330	     */
331	    private void requireCityHasCapacity(String city) {
332	        long cityOwners = this.clinicService.findAllOwners().stream()
333	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
334	            .count();
335	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
336	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
337	        }
338	    }
339	
340	    /**
341	     * Rejects creating an owner who shares a household (see {@link #findHouseholdMembers}) with an existing owner,
342	     * unless the request opts in by setting {@code sharesHousehold} to {@code true}.
343	     *
344	     * @param ownerFieldsDto the incoming owner payload
345	     * @throws DuplicateOwnerException if another owner already belongs to the same household and the request does not
346	     *                                 set {@code sharesHousehold}
347	     */
348	    private void requireUniqueHousehold(OwnerFieldsDto ownerFieldsDto) {
349	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
350	            return;
351	        }
352	        if (!findHouseholdMembers(ownerFieldsDto).isEmpty()) {
353	            throw new DuplicateOwnerException(
354	                "an owner with the same last name and address already exists in this household");
355	        }
356	    }
357	
358	    /**
359	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
360	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
361	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
362	     * incidental formatting differences and abbreviation variants do not affect membership.
363	     *
364	     * @param ownerFieldsDto the incoming owner payload
365	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
366	     *         them; empty when none match
367	     */
368	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
369	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
370	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
371	        return this.clinicService.findAllOwners().stream()
372	            .filter(existing -> collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
373	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
374	            .toList();
375	    }
376	
377	    /**
378	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
379	     * space. Case is deliberately preserved here; callers compare the result case-insensitively.
380	     *
381	     * @param value the raw field value, may be {@code null}
382	     * @return the whitespace-collapsed value, or an empty string when {@code null}
383	     */
384	    private String collapseWhitespace(String value) {
385	        if (value == null) {
386	            return "";
387	        }
388	        return value.strip().replaceAll("\\s+", " ");
389	    }
390	
391	    /**
392	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
393	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
394	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
395	     * identifier is derived deterministically from the household's last name and address, so every member of the same
396	     * household resolves to the same stable value regardless of creation order. Existing members that predate the
397	     * feature and still lack the identifier are backfilled so the whole household shares it.
398	     *
399	     * @param owner          the newly mapped owner about to be saved
400	     * @param ownerFieldsDto the incoming owner payload
401	     */
402	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
403	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
404	            return;
405	        }
406	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
407	        if (members.isEmpty()) {
408	            return;
409	        }
410	        String householdId = generateHouseholdId(ownerFieldsDto);
411	        owner.setHouseholdId(householdId);
412	        for (Owner member : members) {
413	            if (!householdId.equals(member.getHouseholdId())) {
414	                member.setHouseholdId(householdId);
415	                this.clinicService.saveOwner(member);
416	            }
417	        }
418	    }
419	
420	    /**
421	     * Derives a household's stable identifier, formatted {@code HH-<12 hex chars>}, from the case-insensitive,
422	     * whitespace-collapsed last name and the normalized address (see {@link AddressNormalizer}). Being a pure function
423	     * of those fields, it is identical for every owner in the same household and never changes over time.
424	     *
425	     * @param ownerFieldsDto the incoming owner payload
426	     * @return the household identifier
427	     */
428	    private String generateHouseholdId(OwnerFieldsDto ownerFieldsDto) {
429	        String key = collapseWhitespace(ownerFieldsDto.getLastName()).toLowerCase()
430	            + "\n" + addressNormalizer.normalize(ownerFieldsDto.getAddress()).toLowerCase();
431	        try {
432	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
433	            StringBuilder hex = new StringBuilder();
434	            for (int i = 0; i < 6; i++) {
435	                hex.append(String.format("%02X", digest[i]));
436	            }
437	            return "HH-" + hex;
438	        } catch (NoSuchAlgorithmException ex) {
439	            throw new IllegalStateException("SHA-256 is not available", ex);
440	        }
441	    }
442	
443	    /**
444	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
445	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
446	     * household is counted as a household of one.
447	     *
448	     * @param owner the owner whose household size should be resolved
449	     */
450	    private void populateHouseholdMemberCount(Owner owner) {
451	        String householdId = owner.getHouseholdId();
452	        if (householdId == null) {
453	            owner.setHouseholdMemberCount(1);
454	            return;
455	        }
456	        long members = this.clinicService.findAllOwners().stream()
457	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
458	            .count();
459	        owner.setHouseholdMemberCount((int) members);
460	    }
461	
462	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
463	    @Override
464	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
465	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
466	        if (currentOwner == null) {
467	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
468	        }
469	        currentOwner.setAddress(ownerFieldsDto.getAddress());
470	        currentOwner.setCity(ownerFieldsDto.getCity());
471	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
472	        currentOwner.setLastName(ownerFieldsDto.getLastName());
473	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
474	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
475	        this.clinicService.saveOwner(currentOwner);
476	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
477	    }
478	
479	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
480	    @Transactional
481	    @Override
482	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
483	        Owner owner = this.clinicService.findOwnerById(ownerId);
484	        if (owner == null) {
485	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
486	        }
487	        this.clinicService.deleteOwner(owner);
488	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
489	    }
490	
491	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
492	    @Override
493	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
494	        Owner owner = this.clinicService.findOwnerById(ownerId);
495	        if (owner == null) {
496	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
497	        }
498	        HttpHeaders headers = new HttpHeaders();
499	        Pet pet = petMapper.toPet(petFieldsDto);
500	        owner.setId(ownerId);
501	        pet.setOwner(owner);
502	        pet.getType().setName(null);
503	        this.clinicService.savePet(pet);
504	        PetDto petDto = petMapper.toPetDto(pet);
505	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
506	            .buildAndExpand(pet.getId()).toUri());
507	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
508	    }
509	
510	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
511	    @Override
512	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
513	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
514	        if (currentOwner != null) {
515	            Pet currentPet = this.clinicService.findPetById(petId);
516	            if (currentPet != null) {
517	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
518	                currentPet.setName(petFieldsDto.getName());
519	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
520	                this.clinicService.savePet(currentPet);
521	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
522	            }
523	        }
524	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
525	    }
526	
527	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
528	    @Override
529	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
530	        HttpHeaders headers = new HttpHeaders();
531	        Visit visit = visitMapper.toVisit(visitFieldsDto);
532	        Pet pet = new Pet();
533	        pet.setId(petId);
534	        visit.setPet(pet);
535	        this.clinicService.saveVisit(visit);
536	        VisitDto visitDto = visitMapper.toVisitDto(visit);
537	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
538	            .buildAndExpand(visit.getId()).toUri());
539	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
540	    }
541	
542	
543	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
544	    @Override
545	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
546	        Owner owner = this.clinicService.findOwnerById(ownerId);
547	        if (owner != null) {
548	            Pet pet = owner.getPet(petId);
549	            if (pet != null) {
550	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
551	            }
552	        }
553	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
554	    }
555	}
